def list_orders(connection: sqlite3.Connection, account_id: str) -&gt; list[tuple[int, int]]:
    try:
        query = "SELECT id, total_cents FROM orders WHERE account_id = ?"
        return connection.execute(query, (account_id,)).fetchall()
    except sqlite3.Error as e:
        raise RuntimeError(f"Failed to list orders for account {account_id}") from e

